<script setup lang="ts">
import {useParameterTransaction} from './useParameterTransaction';
import SeriesPreview from './SeriesPreview.vue';
import ParameterDialog from './ParameterDialog.vue';
const settingsOpen=ref(false);
import {apiError} from './apiError';
import {ref,watch,computed} from 'vue';
const props=defineProps<{draftMode?:boolean;projectId:string;csv:string}>();const emit=defineEmits<{apply:[csv:string];window:[csv:string]}>();const growth=ref(.05);const wind=ref(1.05);const pv=ref(1.05);const window=ref(36);const seed=ref(42);const result=ref<any>(null);const busy=ref(false);const error=ref('');const inputSnapshot=ref('');const stale=computed(()=>!!result.value && inputSnapshot.value!==props.csv);watch(()=>props.projectId,()=>{result.value=null;error.value=''});
async function run(){commitSettings(false);busy.value=true;error.value='';result.value=null;const submittedProject=props.projectId;const submittedCsv=props.csv;try{const r=await fetch('/api/source-analysis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:props.projectId,csv:props.csv,growth:growth.value,wind_scale:wind.value,pv_scale:pv.value,window:window.value,seed:seed.value})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(submittedProject===props.projectId){result.value=d;inputSnapshot.value=submittedCsv}}catch(e){error.value=String(e)}finally{busy.value=false}}
function exportWindow(){const blob=new Blob([JSON.stringify(result.value.extreme_window,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='极端窗口快照.json';a.click();URL.revokeObjectURL(url)}
const commitSettings=useParameterTransaction(settingsOpen,{growth,wind,pv,window,seed});
</script>
<template><article><h3>课题2 / 源荷增长与极端窗口分析</h3><p>使用当前源荷数据计算净负荷、经验分位边界和高压力窗口。增长参数按历史形态生成水平年输入。</p><button class="settings-trigger" @click="settingsOpen=true">增长与极端窗口参数</button><ParameterDialog transactional @apply="commitSettings()" v-model:open="settingsOpen" title="增长与极端窗口参数"><div class="grid"><div><label class="field">负荷增长比例<input type="number" step=".01" v-model.number="growth"></label><label class="field">风电缩放系数<input type="number" step=".05" v-model.number="wind"></label></div><div><label class="field">光伏缩放系数<input type="number" step=".05" v-model.number="pv"></label><label class="field">窗口长度 / h<input type="number" min="2" max="168" v-model.number="window"></label></div></div><label class="field">合成天气随机种子<input type="number" min="0" v-model.number="seed"></label><button @click="run" :disabled="busy||!projectId">{{busy?'分析中…':'计算源荷特征与窗口'}}</button><p class="error" v-if="error">{{error}}</p></ParameterDialog><SeriesPreview :csv="result?.extreme_window?.csv||csv"/><template v-if="result"><p>{{result.scope}}</p><p v-if="stale" class="notice">源荷数据已变化，下方为上次分析结果。请重新分析后应用窗口。</p><h3>压力窗口前10名</h3><div class="scroll"><table><tr><th>开始</th><th>结束</th><th>评分</th><th>最长低出力 / h</th></tr><tr v-for="r in result.windows"><td>{{r.window_start}}</td><td>{{r.window_end}}</td><td>{{r.extreme_window_score.toFixed(2)}}</td><td>{{r.max_low_re_continuous_hours}}</td></tr></table></div><h3>最高评分极端窗口</h3><p>{{result.extreme_window.scope}}</p><div class="actions"><button :disabled="stale" @click="emit('apply',result.extreme_window.csv)">{{draftMode?'选用极端片段作为输入草稿':'将极端窗口应用到当前工程'}}</button><button :disabled="stale" @click="emit('window',result.extreme_window.csv)">{{draftMode?'选用片段用于嵌入':'送入生产序列嵌入'}}</button><button @click="exportWindow">导出窗口与合成天气快照</button></div><details><summary>预览窗口源荷与合成风速</summary><div class="scroll"><table><tr><th>时间</th><th>负荷 / kW</th><th>风电 / kW</th><th>光伏 / kW</th><th>合成风速 / m/s</th></tr><tr v-for="(r,i) in result.extreme_window.rows"><td>{{r.timestamp}}</td><td>{{r.load_kw}}</td><td>{{r.wind_kw}}</td><td>{{r.pv_kw}}</td><td>{{result.extreme_window.hazard[i].wind_speed.toFixed(2)}}</td></tr></table></div></details><details><summary>查看经验概率边界</summary><pre>{{JSON.stringify({load:result.load_boundary,renewable:result.renewable_boundary},null,2)}}</pre></details><button :disabled="stale" @click="emit('apply',result.projected_csv)">{{draftMode?'选用增长序列到草稿':'将增长后序列应用到当前工程'}}</button><p>应用后替换工作区源荷时序，需保存工程并重新计算；已有故障场景将解除。</p></template></article></template>
